INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1000, "vo_minigame_1013_icon_2_002_001", 1, 2, "調子が上がって\nきたなっ", 2, 2, 3000, "vo_minigame_1013_icon_1_002_001", "訓練はまだ\nここからですわ");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (5000, "vo_minigame_1013_icon_2_003_001", 2, 2, "ほらほら、\nまだいけるだろ？", 2, 2, 3000, "vo_minigame_1013_icon_1_003_001", "クスクス、悪くない\n流れですわね");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (10000, "vo_minigame_1013_icon_2_004_001", 3, 2, "へへっ、おまえら\nやるじゃねえか！", 2, 3, 3000, "vo_minigame_1013_icon_1_004_001", "すばらしい\n記録ですわ");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (10000, "vo_minigame_1013_icon_2_005_001", 4, 2, "あたしたちはまだ\n止まらねえぜ！", 3, 3, 3000, "vo_minigame_1013_icon_1_005_001", "乗りに乗って\nいますわね");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (10000, "vo_minigame_1013_icon_2_005_002", 5, 2, "見てろよ！\nマコト班の快進撃だ！", 3, 3, 3000, "vo_minigame_1013_icon_1_005_002", "まだまだ行きます\nついてきなさい");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (10000, "vo_minigame_1013_icon_2_005_003", 6, 2, "うおぉぉっ！\n絶好調だぜ！", 3, 3, 3000, "vo_minigame_1013_icon_1_005_003", "エリコ班の\n本領発揮ですわ！");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (0, "vo_minigame_1013_icon_2_006_001", 7, 2, "どこまで行けるか\n楽しみだなっ！", 4, 3, 3000, "vo_minigame_1013_icon_1_006_001", "ここからは\n前人未到の領域です！");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1, "vo_minigame_1013_icon_2_007_001", 8, 3, "まだ諦めんなよっ", 5, 4, 1000, "vo_minigame_1013_icon_1_007_001", "厄介でしたわ…");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1, "vo_minigame_1013_icon_2_007_002", 9, 3, "冷やっとしたぜ…！", 5, 4, 1000, "vo_minigame_1013_icon_1_007_002", "油断大敵です");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1, "vo_minigame_1013_icon_2_007_003", 10, 3, "弱音を吐くなっ", 5, 4, 1000, "vo_minigame_1013_icon_1_007_003", "忌々しいっ…");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (99, "vo_minigame_1013_icon_2_008_001", 11, 4, "マコト班集合！", 6, 3, 1500, "vo_minigame_1013_icon_1_008_001", "大所帯ですわね");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (99, "vo_minigame_1013_icon_2_008_002", 12, 4, "連携してくぞ！", 6, 3, 1500, "vo_minigame_1013_icon_1_008_002", "エリコ班へようこそ");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (0, "vo_minigame_1013_icon_2_020_001", 13, 1, "みんなに力を！", 8, 6, 3000, "vo_minigame_1013_icon_1_020_001", "ナナカちゃんに\nお任せあれ");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (0, "vo_minigame_1013_icon_2_022_001", 14, 1, "任せてくれたまえ", 9, 7, 3000, "vo_minigame_1013_icon_1_022_001", "はっはっは！\n任せろ！");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (0, "vo_minigame_1013_icon_2_023_001", 15, 1, "ほな、いきまひょか", 10, 8, 3000, "vo_minigame_1013_icon_1_023_001", "どんどんいくわよ");
